export const ToolLogo = ({ tool, className }: { tool: ToolSlug; className?: string }) => {
  const logo: Logo = toolLogos[tool];
  return (
    <svg viewBox={logo.viewBox ?? "0 0 24 24"} role="img" aria-label={logo.title} className={className} fill={logo.hex}>
      <path d={logo.path} />
    </svg>
  );
};
